+import { test } from "node:test";
+import assert from "node:assert/strict";
+import { applyDiscount, discountCents } from "../src/pricing/discount.ts";
+
+test("REQ-17 pricing: discounts round to the nearest cent, half-cents up", () => {
+  assert.equal(discountCents(105, 10), 11); // 10.5 -> 11
+  assert.equal(discountCents(104, 10), 10); // 10.4 -> 10
+  assert.equal(discountCents(106, 10), 11); // 10.6 -> 11
+  assert.equal(discountCents(1, 50), 1); // 0.5 -> 1
+  assert.equal(applyDiscount(105, 10), 94);
+});
+
+test("REQ-17 pricing: zero and full discounts are exact", () => {
+  assert.equal(applyDiscount(105, 0), 105);
+  assert.equal(applyDiscount(105, 100), 0);
+});
+
+test("pricing: invalid inputs are rejected", () => {
+  assert.throws(() => applyDiscount(105, -1), RangeError);
+  assert.throws(() => applyDiscount(105, 101), RangeError);
+  assert.throws(() => applyDiscount(105, 10.5), RangeError);
+  assert.throws(() => applyDiscount(-1, 10), RangeError);
+  assert.throws(() => applyDiscount(1.5, 10), RangeError);
+});

